import type { PronunciationSentenceRow } from './types';
import type { TargetLanguage } from './targetLanguage';

// Formats the Japanese/Mandarin/Arabic lessons generated by
// /api/ai/localized-lesson into chat messages (with the table/passage tokens
// MessageContent renders) and keeps a compact text context for feedback.

export type LocalizedLanguage = Exclude<TargetLanguage, 'English'>;
export type LocalizedFocus = 'vocabulary' | 'grammar' | 'pronunciation' | 'speaking' | 'reading' | 'writing';

type Reading = { word: string; reading: string; meaning: string };

export type LocalizedVocabularyLesson = {
  rows: Array<{ word: string; reading: string; meaning: string; pos: string; note: string; example: string; exampleReading: string; exampleMeaning: string }>;
};
export type LocalizedPronunciationLesson = {
  rows: Array<{ sentence: string; reading: string; focus: string; tip: string; meaning: string }>;
};
export type LocalizedGrammarLesson = {
  title: string;
  explanation: string;
  patterns: Array<{ pattern: string; meaning: string }>;
  examples: Array<{ sentence: string; reading: string; meaning: string }>;
  mistakes: Array<{ wrong: string; right: string; why: string }>;
  drills: string[];
};
export type LocalizedSpeakingLesson = {
  opener: { text: string; reading: string; meaning: string };
  rows: Array<{ prompt: string; grammarFocus: string; usefulPattern: string; example: string; exampleReading: string; exampleMeaning: string }>;
};
export type LocalizedReadingLesson = {
  title: string;
  passage: string;
  passageReading: string;
  translation: string;
  glossary: Reading[];
  questions: string[];
  answers: string[];
};
export type LocalizedWritingLesson = {
  prompt: string;
  requirements: string[];
  patterns: Array<{ pattern: string; reading: string; meaning: string }>;
  wordBank: Reading[];
  starter: { text: string; reading: string };
  modelAnswer: string;
};

export type LocalizedLessonPayload = {
  vocabulary: LocalizedVocabularyLesson;
  grammar: LocalizedGrammarLesson;
  pronunciation: LocalizedPronunciationLesson;
  speaking: LocalizedSpeakingLesson;
  reading: LocalizedReadingLesson;
  writing: LocalizedWritingLesson;
};

export type FormattedLocalizedLesson = {
  message: string;
  context: string;
  vocabularyWords: string[];
  pronunciationRows: PronunciationSentenceRow[];
};

export type LocalizedFeedbackResult = {
  status: 'correct' | 'almost' | 'incorrect';
  score: number | null;
  feedback: string;
  corrected: string;
  correctedReading: string;
  completedItems: string[];
  nextTask: string;
};

type LanguageCopy = {
  apiId: 'japanese' | 'mandarin' | 'arabic';
  name: string;
  reading: string;
  script: string;
  checks: string;
  levels: Record<string, string>;
};

